import type { Action } from 'svelte/action';

// A click event generated by the keyboard has a click count (detail) of zero
const KEYBOARD_CLICK_DETAIL = 0;

type FocusTarget = HTMLElement | SVGElement;

/** Focus return for a dismissible container, created once per component instance. */
export interface FocusReturn {
  /**
   * Svelte action for the container's root element. It remembers where focus
   * came from before it entered the container.
   */
  track: Action<HTMLElement>;
  /**
   * Moves focus back to where it came from. Call it from the dismiss handler
   * with the click event, before the container is hidden: dismissing removes the
   * focused button, and without this the browser drops focus to the document body.
   */
  restore: (event: MouseEvent) => void;
}

/**
 * Creates the focus return for one dismissible container (an alert or a banner).
 * Destructure the result and put `use:track` on the container's root element.
 */
export function createFocusReturn(): FocusReturn {
  let root: HTMLElement | undefined;
  let returnFocusTo: FocusTarget | null = null;

  function handleFocusIn(event: FocusEvent) {
    const from = event.relatedTarget;
    // Only focus arriving from an element outside the container replaces the target.
    // Moving between controls inside the container keeps it, and so does focus with no
    // related element (the window or tab regaining focus while a control in the
    // container is focused, or a click on plain page content). That can leave an older
    // target in place after a later entry from the page body, which is harmless:
    // restore only uses it while it is still connected and outside the container.
    if (!(from instanceof HTMLElement || from instanceof SVGElement)) return;
    if (root?.contains(from)) return;
    returnFocusTo = from;
  }

  function handleFocusOut(event: FocusEvent) {
    // Focus left for the page body (a click on non-focusable content): forget the
    // target, so a later Tab back in and keyboard dismiss does not jump to a field
    // that may be far away. A window or tab blur also fires focusout with no related
    // element, but the document has lost focus by then, so the target is kept for
    // the refocus. Moves within the container, or to another element (re-entry sets
    // the target again), leave it alone.
    if (event.relatedTarget === null && document.hasFocus()) {
      returnFocusTo = null;
    }
  }

  const track: Action<HTMLElement> = node => {
    root = node;
    node.addEventListener('focusin', handleFocusIn);
    node.addEventListener('focusout', handleFocusOut);
    return {
      destroy() {
        node.removeEventListener('focusin', handleFocusIn);
        node.removeEventListener('focusout', handleFocusOut);
        root = undefined;
        returnFocusTo = null;
      },
    };
  };

  function restore(event: MouseEvent) {
    // Only for keyboard activation (Enter or Space on the button reports a click
    // with no click count). A mouse click leaves focus alone, so it does not jump
    // back to a far-away field and scroll the page. Also only when focus is
    // inside the container; otherwise leave focus where it is.
    if (
      event.detail === KEYBOARD_CLICK_DETAIL &&
      root?.contains(document.activeElement) &&
      returnFocusTo?.isConnected &&
      !root.contains(returnFocusTo)
    ) {
      returnFocusTo.focus();
    }
  }

  return { track, restore };
}
